"""SQLite-backed repository using append-only IntentStore for events/audit."""

from __future__ import annotations

import os
import threading
from typing import Any

from pydantic import BaseModel, ValidationError

from core.intent_store import IntentStore
from core.models import CustomerOutcome, Evidence, Job, Outcome, Step
from core.repository import Repository


class SQLiteRepository(Repository):
    def __init__(self, db_path: str | None = None) -> None:
        if db_path is None:
            db_path = os.environ.get("AGENTIC_ODI_DB", os.path.expanduser("~/.agentic-odi/odi.db"))
        os.makedirs(os.path.dirname(db_path) or ".", exist_ok=True)
        self._lock = threading.RLock()
        self.store = IntentStore(db_path, check_same_thread=False)
        self._last_event_id = 0
        self._load_snapshot()

    def _load_snapshot(self) -> None:
        self.jobs: dict[str, Job] = {}
        self.steps: dict[str, Step] = {}
        self.outcomes: dict[str, Outcome] = {}
        self.customer_outcomes: dict[str, CustomerOutcome] = {}
        self.evidence: dict[str, Evidence] = {}
        self._last_event_id = 0
        for ev in self.store.get_stream():
            self._apply_event(ev)

    def _sync(self) -> None:
        for ev in self.store.get_stream():
            if ev["id"] > self._last_event_id:
                self._apply_event(ev)

    def _apply_event(self, ev: dict) -> None:
        et = ev["type"]
        p = ev["payload"]
        if et == "JOB_CREATED":
            self.jobs[p["id"]] = Job.model_validate(p)
        elif et == "STEP_CREATED":
            self.steps[p["id"]] = Step.model_validate(p)
        elif et == "OUTCOME_CREATED":
            self.outcomes[p["id"]] = Outcome.model_validate(p)
        elif et == "CUSTOMER_OUTCOME_CREATED":
            self.customer_outcomes[p["id"]] = CustomerOutcome.model_validate(p)
        elif et == "EVIDENCE_CREATED":
            self.evidence[p["id"]] = Evidence.model_validate(p)
        elif et == "JOB_UPDATED":
            self._merge_updates(self.jobs, p, Job)
        elif et == "STEP_UPDATED":
            self._merge_updates(self.steps, p, Step)
        elif et == "OUTCOME_UPDATED":
            self._merge_updates(self.outcomes, p, Outcome)
        elif et == "CUSTOMER_OUTCOME_UPDATED":
            self._merge_updates(self.customer_outcomes, p, CustomerOutcome)
        elif et == "JOB_DELETED":
            job_id = p["id"]
            self.jobs.pop(job_id, None)
            for key in [k for k, v in self.steps.items() if v.job_id == job_id]:
                del self.steps[key]
            for key in [k for k, v in self.outcomes.items() if v.job_id == job_id]:
                del self.outcomes[key]
            for key in [k for k, v in self.customer_outcomes.items() if v.job_id == job_id]:
                del self.customer_outcomes[key]
            for key in [
                k
                for k, v in self.evidence.items()
                if v.job_id == job_id
                or (v.step_id is not None and v.step_id not in self.steps)
                or (v.outcome_id is not None and v.outcome_id not in self.outcomes)
            ]:
                del self.evidence[key]
        elif et == "STEP_DELETED":
            step_id = p["id"]
            self.steps.pop(step_id, None)
            for key in [k for k, v in self.outcomes.items() if v.step_id == step_id]:
                del self.outcomes[key]
            for key in [k for k, v in self.customer_outcomes.items() if v.step_id == step_id]:
                del self.customer_outcomes[key]
            for key in [
                k
                for k, v in self.evidence.items()
                if v.step_id == step_id
                or (v.outcome_id is not None and v.outcome_id not in self.outcomes)
            ]:
                del self.evidence[key]
        elif et == "OUTCOME_DELETED":
            outcome_id = p["id"]
            self.outcomes.pop(outcome_id, None)
            for key in [k for k, v in self.evidence.items() if v.outcome_id == outcome_id]:
                del self.evidence[key]
        elif et == "EVIDENCE_DELETED":
            self.evidence.pop(p["id"], None)
        elif et == "CUSTOMER_OUTCOME_DELETED":
            self.customer_outcomes.pop(p["id"], None)
        self._last_event_id = max(self._last_event_id, ev["id"])

    @staticmethod
    def _merge_updates(entities: dict[str, Any], p: dict, model: type[BaseModel]) -> None:
        entity = entities.get(p["id"])
        if entity is None:
            return
        current = entity.model_dump(exclude_unset=True)
        current.update(p.get("updates", {}))
        try:
            entities[p["id"]] = model.model_validate(current)
        except ValidationError:
            pass

    def add_job(self, job: Job) -> Job:
        with self._lock:
            self.store.append("JOB_CREATED", job.model_dump())
            self._sync()
            return job

    def list_jobs(self) -> list[Job]:
        with self._lock:
            self._sync()
            return list(self.jobs.values())

    def get_job(self, job_id: str) -> Job | None:
        with self._lock:
            self._sync()
            return self.jobs.get(job_id)

    def update_job(self, job_id: str, updates: dict) -> Job | None:
        with self._lock:
            self._sync()
            job = self.jobs.get(job_id)
            if not job:
                return None
            current = job.model_dump(exclude_unset=True)
            current.update(updates)
            new_job = job.model_validate(current)
            self.store.append("JOB_UPDATED", {"id": job_id, "updates": updates})
            self._sync()
            return new_job

    def delete_job(self, job_id: str) -> bool:
        with self._lock:
            self._sync()
            if job_id not in self.jobs:
                return False
            self.store.append("JOB_DELETED", {"id": job_id})
            self._sync()
            return True

    def add_step(self, step: Step) -> Step:
        with self._lock:
            self.store.append("STEP_CREATED", step.model_dump())
            self._sync()
            return step

    def get_step(self, step_id: str) -> Step | None:
        with self._lock:
            self._sync()
            return self.steps.get(step_id)

    def get_steps_for_job(self, job_id: str) -> list[Step]:
        with self._lock:
            self._sync()
            return [s for s in self.steps.values() if s.job_id == job_id]

    def update_step(self, step_id: str, updates: dict) -> Step | None:
        with self._lock:
            self._sync()
            step = self.steps.get(step_id)
            if not step:
                return None
            current = step.model_dump(exclude_unset=True)
            current.update(updates)
            new_step = step.model_validate(current)
            self.store.append("STEP_UPDATED", {"id": step_id, "updates": updates})
            self._sync()
            return new_step

    def delete_step(self, step_id: str) -> bool:
        with self._lock:
            self._sync()
            if step_id not in self.steps:
                return False
            self.store.append("STEP_DELETED", {"id": step_id})
            self._sync()
            return True

    def add_outcome(self, outcome: Outcome) -> Outcome:
        with self._lock:
            self.store.append("OUTCOME_CREATED", outcome.model_dump())
            self._sync()
            return outcome

    def get_outcome(self, outcome_id: str) -> Outcome | None:
        with self._lock:
            self._sync()
            return self.outcomes.get(outcome_id)

    def get_outcomes(self, job_id: str, step_id: str | None = None) -> list[Outcome]:
        with self._lock:
            self._sync()
            outs = [o for o in self.outcomes.values() if o.job_id == job_id]
            if step_id is not None:
                outs = [o for o in outs if o.step_id == step_id]
            return outs

    def update_outcome(self, outcome_id: str, updates: dict) -> Outcome | None:
        with self._lock:
            self._sync()
            outcome = self.outcomes.get(outcome_id)
            if not outcome:
                return None
            current = outcome.model_dump(exclude_unset=True)
            current.update(updates)
            new_outcome = outcome.model_validate(current)
            self.store.append("OUTCOME_UPDATED", {"id": outcome_id, "updates": updates})
            self._sync()
            return new_outcome

    def delete_outcome(self, outcome_id: str) -> bool:
        with self._lock:
            self._sync()
            if outcome_id not in self.outcomes:
                return False
            self.store.append("OUTCOME_DELETED", {"id": outcome_id})
            self._sync()
            return True

    def add_customer_outcome(self, co: CustomerOutcome) -> CustomerOutcome:
        with self._lock:
            self.store.append("CUSTOMER_OUTCOME_CREATED", co.model_dump())
            self._sync()
            return co

    def get_customer_outcome(self, outcome_id: str) -> CustomerOutcome | None:
        with self._lock:
            self._sync()
            return self.customer_outcomes.get(outcome_id)

    def list_customer_outcomes(self, job_id: str | None = None) -> list[CustomerOutcome]:
        with self._lock:
            self._sync()
            if job_id is None:
                return list(self.customer_outcomes.values())
            return [co for co in self.customer_outcomes.values() if co.job_id == job_id]

    def update_customer_outcome(
        self, outcome_id: str, updates: dict[str, Any]
    ) -> CustomerOutcome | None:
        with self._lock:
            self._sync()
            co = self.customer_outcomes.get(outcome_id)
            if not co:
                return None
            current = co.model_dump(exclude_unset=True)
            current.update(updates)
            try:
                new_co = co.model_validate(current)
            except ValidationError:
                return None
            self.store.append("CUSTOMER_OUTCOME_UPDATED", {"id": outcome_id, "updates": updates})
            self._sync()
            return new_co

    def add_evidence(self, evidence: Evidence) -> Evidence:
        with self._lock:
            self.store.append("EVIDENCE_CREATED", evidence.model_dump())
            self._sync()
            return evidence

    def get_evidence(self, evidence_id: str) -> Evidence | None:
        with self._lock:
            self._sync()
            return self.evidence.get(evidence_id)

    def list_evidence(
        self,
        job_id: str | None = None,
        step_id: str | None = None,
        outcome_id: str | None = None,
    ) -> list[Evidence]:
        with self._lock:
            self._sync()
            items = list(self.evidence.values())
            if job_id is not None:
                items = [item for item in items if item.job_id == job_id]
            if step_id is not None:
                items = [item for item in items if item.step_id == step_id]
            if outcome_id is not None:
                items = [item for item in items if item.outcome_id == outcome_id]
            return items

    def delete_evidence(self, evidence_id: str) -> bool:
        with self._lock:
            self._sync()
            if evidence_id not in self.evidence:
                return False
            self.store.append("EVIDENCE_DELETED", {"id": evidence_id})
            self._sync()
            return True

    def delete_customer_outcome(self, outcome_id: str) -> bool:
        with self._lock:
            self._sync()
            if outcome_id in self.customer_outcomes:
                self.store.append("CUSTOMER_OUTCOME_DELETED", {"id": outcome_id})
                self._sync()
                return True
            return False

    def clear(self) -> None:
        with self._lock:
            self.store.clear()
            self._load_snapshot()

"""Backend abstraction for CLI."""

from __future__ import annotations

import asyncio
import json
import os
from abc import ABC, abstractmethod
from collections.abc import Callable
from dataclasses import dataclass
from typing import Any

import typer
from core import (
    CustomerOutcomeNotFoundError,
    EvidenceNotFoundError,
    JobNotFoundError,
    ODIService,
    OutcomeNotFoundError,
    StepNotFoundError,
    ValueOutOfRangeError,
    build_repository,
    customer_outcome_not_found,
    job_not_found,
    odi_schema,
)
from pydantic import ValidationError

_VALUE_RANGE_ERROR = "Error: importance and satisfaction must be between 1.0 and 10.0"

_CUSTOMER_VALUE_FIELDS = (
    "direction",
    "unit_of_measure",
    "object_of_control",
    "contextual_clarifier",
    "statement",
    "importance",
    "satisfaction",
    "value_metrics",
)

_BUSINESS_VALUE_FIELDS = {
    "category": "category",
    "business_statement": "statement",
    "detail": "detail",
    "estimated_annual_value": "estimated_annual_value",
    "confidence": "confidence",
}


def _job_id_error(job_id: str) -> str:
    return f"Error: Job with ID {job_id} not found."


def _step_id_error(step_id: str) -> str:
    return f"Error: Step with ID {step_id} not found."


def _outcome_id_error(outcome_id: str) -> str:
    return f"Error: Outcome with ID {outcome_id} not found."


def _evidence_id_error(evidence_id: str) -> str:
    return f"Error: Evidence with ID {evidence_id} not found."


def _call_mcp(tool: str, args: dict, mcp_url: str) -> str:
    from fastmcp import Client

    async def _run() -> str:
        async with Client(mcp_url) as client:
            result = await client.call_tool(tool, args)
            return result.content[0].text  # type: ignore[index]

    try:
        return asyncio.run(_run())
    except Exception as exc:  # noqa: BLE001
        typer.echo(f"Error: could not reach MCP server at {mcp_url}: {exc}", err=True)
        raise typer.Exit(code=1) from exc


class Backend(ABC):
    @abstractmethod
    def call(self, tool_name: str, args: dict) -> str:
        raise NotImplementedError


class LocalBackend(Backend):
    def __init__(self, db_path: str | None = None) -> None:
        self._db_path = db_path
        self._service: ODIService | None = None
        self._handlers: dict[str, Callable[[dict], str]] = {
            "add_job": self._add_job,
            "get_jobs": self._get_jobs,
            "get_job": self._get_job,
            "update_job": self._update_job,
            "delete_job": self._delete_job,
            "add_step": self._add_step,
            "get_job_map": self._get_job_map,
            "get_step": self._get_step,
            "update_step": self._update_step,
            "delete_step": self._delete_step,
            "add_outcome": self._add_outcome,
            "get_outcomes": self._get_outcomes,
            "get_outcome": self._get_outcome,
            "update_outcome": self._update_outcome,
            "delete_outcome": self._delete_outcome,
            "add_customer_outcome": self._add_customer_outcome,
            "get_customer_outcome": self._get_customer_outcome,
            "list_customer_outcomes": self._list_customer_outcomes,
            "update_customer_outcome": self._update_customer_outcome,
            "delete_customer_outcome": self._delete_customer_outcome,
            "add_evidence": self._add_evidence,
            "get_evidence": self._get_evidence,
            "list_evidence": self._list_evidence,
            "delete_evidence": self._delete_evidence,
            "promote_evidence": self._promote_evidence,
            "get_odi_schema": self._get_odi_schema,
            "compute_opportunity": self._compute_opportunity,
        }

    @property
    def service(self) -> ODIService:
        if self._service is None:
            self._service = ODIService(build_repository(self._db_path))
        return self._service

    def call(self, tool_name: str, args: dict) -> str:
        handler = self._handlers.get(tool_name)
        if handler is None:
            raise NotImplementedError(f"Unknown tool: {tool_name}")
        return handler(args)

    def _add_job(self, args: dict) -> str:
        job = self.service.add_job(name=args["name"], description=args.get("description"))
        return f"Job created successfully: {job.model_dump_json()}"

    def _get_jobs(self, args: dict) -> str:
        return json.dumps([job.model_dump() for job in self.service.get_jobs()])

    def _get_job(self, args: dict) -> str:
        job_id = args["job_id"]
        job = self.service.get_job(job_id)
        if job is None:
            return _job_id_error(job_id)
        return job.model_dump_json()

    def _update_job(self, args: dict) -> str:
        updates = {key: args[key] for key in ("name", "description") if key in args}
        try:
            job = self.service.update_job(args["job_id"], updates)
        except JobNotFoundError:
            return job_not_found(args["job_id"])
        return f"Job updated successfully: {job.model_dump_json()}"

    def _delete_job(self, args: dict) -> str:
        job_id = args["job_id"]
        try:
            self.service.delete_job(job_id)
        except JobNotFoundError:
            return job_not_found(job_id)
        return f"Job deleted successfully: {job_id}"

    def _add_step(self, args: dict) -> str:
        try:
            step = self.service.add_step(
                job_id=args["job_id"], name=args["name"], order=args["order"]
            )
        except JobNotFoundError:
            return job_not_found(args["job_id"])
        return f"Step created successfully: {step.model_dump_json()}"

    def _get_job_map(self, args: dict) -> str:
        job_id = args["job_id"]
        if self.service.get_job(job_id) is None:
            return _job_id_error(job_id)
        steps = self.service.get_job_map(job_id)
        return json.dumps([step.model_dump() for step in steps])

    def _get_step(self, args: dict) -> str:
        step_id = args["step_id"]
        step = self.service.get_step(step_id)
        if step is None:
            return _step_id_error(step_id)
        return step.model_dump_json()

    def _update_step(self, args: dict) -> str:
        updates = {key: args[key] for key in ("name", "order") if key in args}
        try:
            step = self.service.update_step(args["step_id"], updates)
        except StepNotFoundError:
            return _step_id_error(args["step_id"])
        return f"Step updated successfully: {step.model_dump_json()}"

    def _delete_step(self, args: dict) -> str:
        step_id = args["step_id"]
        try:
            self.service.delete_step(step_id)
        except StepNotFoundError:
            return _step_id_error(step_id)
        return f"Step deleted successfully: {step_id}"

    def _add_outcome(self, args: dict) -> str:
        try:
            outcome = self.service.add_outcome(
                job_id=args["job_id"],
                statement=args["statement"],
                importance=args.get("importance"),
                satisfaction=args.get("satisfaction"),
                step_id=args.get("step_id"),
            )
        except JobNotFoundError:
            return _job_id_error(args["job_id"])
        except StepNotFoundError:
            return _step_id_error(args["step_id"])
        except ValueOutOfRangeError:
            return _VALUE_RANGE_ERROR
        return f"Outcome created successfully: {outcome.model_dump_json()}"

    def _get_outcomes(self, args: dict) -> str:
        job_id = args["job_id"]
        if self.service.get_job(job_id) is None:
            return _job_id_error(job_id)
        outcomes = self.service.get_outcomes(job_id=job_id, step_id=args.get("step_id"))
        return json.dumps([outcome.model_dump() for outcome in outcomes])

    def _get_outcome(self, args: dict) -> str:
        outcome_id = args["outcome_id"]
        outcome = self.service.get_outcome(outcome_id)
        if outcome is None:
            return _outcome_id_error(outcome_id)
        return outcome.model_dump_json()

    def _update_outcome(self, args: dict) -> str:
        updates = {
            key: args[key]
            for key in ("statement", "importance", "satisfaction", "step_id")
            if key in args
        }
        try:
            outcome = self.service.update_outcome(args["outcome_id"], updates)
        except OutcomeNotFoundError:
            return _outcome_id_error(args["outcome_id"])
        except ValueOutOfRangeError:
            return _VALUE_RANGE_ERROR
        return f"Outcome updated successfully: {outcome.model_dump_json()}"

    def _delete_outcome(self, args: dict) -> str:
        outcome_id = args["outcome_id"]
        try:
            self.service.delete_outcome(outcome_id)
        except OutcomeNotFoundError:
            return _outcome_id_error(outcome_id)
        return f"Outcome deleted successfully: {outcome_id}"

    def _add_customer_outcome(self, args: dict) -> str:
        try:
            outcome = self.service.add_customer_outcome(
                job_id=args["job_id"],
                customer_value=args["customer_value"],
                business_value=args["business_value"],
                step_id=args.get("step_id"),
            )
        except JobNotFoundError:
            return _job_id_error(args["job_id"])
        except StepNotFoundError:
            return _step_id_error(args["step_id"])
        except ValidationError as exc:
            return f"Error: {exc}"
        return f"Customer outcome created successfully: {outcome.model_dump_json()}"

    def _get_customer_outcome(self, args: dict) -> str:
        outcome_id = args["outcome_id"]
        try:
            outcome = self.service.get_customer_outcome(outcome_id)
        except CustomerOutcomeNotFoundError:
            return customer_outcome_not_found(outcome_id)
        return outcome.model_dump_json()

    def _list_customer_outcomes(self, args: dict) -> str:
        outcomes = self.service.list_customer_outcomes(args.get("job_id"))
        return json.dumps([outcome.model_dump() for outcome in outcomes])

    def _update_customer_outcome(self, args: dict) -> str:
        outcome_id = args["outcome_id"]
        try:
            existing = self.service.get_customer_outcome(outcome_id)
        except CustomerOutcomeNotFoundError:
            return customer_outcome_not_found(outcome_id)
        customer_value = existing.customer_value.model_dump()
        for field in _CUSTOMER_VALUE_FIELDS:
            if field in args:
                customer_value[field] = args[field]
        business_value = existing.business_value.model_dump()
        for arg_key, field in _BUSINESS_VALUE_FIELDS.items():
            if arg_key in args:
                business_value[field] = args[arg_key]
        updates: dict[str, Any] = {
            "customer_value": customer_value,
            "business_value": business_value,
        }
        if "step_id" in args:
            updates["step_id"] = args["step_id"]
        try:
            outcome = self.service.update_customer_outcome(outcome_id, updates)
        except CustomerOutcomeNotFoundError:
            return customer_outcome_not_found(outcome_id)
        except ValidationError as exc:
            return f"Error: {exc}"
        return f"Customer outcome updated successfully: {outcome.model_dump_json()}"

    def _delete_customer_outcome(self, args: dict) -> str:
        outcome_id = args["outcome_id"]
        try:
            self.service.delete_customer_outcome(outcome_id)
        except CustomerOutcomeNotFoundError:
            return customer_outcome_not_found(outcome_id)
        return f"Customer outcome deleted successfully: {outcome_id}"

    def _add_evidence(self, args: dict) -> str:
        try:
            evidence = self.service.add_evidence(
                source_name=args["source_name"],
                source_kind=args["source_kind"],
                name=args["name"],
                content=args["content"],
                item_type=args.get("item_type", "manual"),
                raw=args.get("raw"),
                job_id=args.get("job_id"),
                step_id=args.get("step_id"),
                outcome_id=args.get("outcome_id"),
            )
        except JobNotFoundError:
            return _job_id_error(args.get("job_id", ""))
        except StepNotFoundError:
            return _step_id_error(args.get("step_id", ""))
        except OutcomeNotFoundError:
            return _outcome_id_error(args.get("outcome_id", ""))
        except ValueError as exc:
            return f"Error: {exc}"
        return f"Evidence created successfully: {evidence.model_dump_json()}"

    def _get_evidence(self, args: dict) -> str:
        evidence_id = args["evidence_id"]
        evidence = self.service.get_evidence(evidence_id)
        if evidence is None:
            return _evidence_id_error(evidence_id)
        return evidence.model_dump_json()

    def _list_evidence(self, args: dict) -> str:
        items = self.service.list_evidence(
            job_id=args.get("job_id"),
            step_id=args.get("step_id"),
            outcome_id=args.get("outcome_id"),
        )
        return json.dumps([item.model_dump() for item in items])

    def _delete_evidence(self, args: dict) -> str:
        evidence_id = args["evidence_id"]
        try:
            self.service.delete_evidence(evidence_id)
        except EvidenceNotFoundError:
            return _evidence_id_error(evidence_id)
        return f"Evidence deleted successfully: {evidence_id}"

    def _promote_evidence(self, args: dict) -> str:
        evidence_id = args["evidence_id"]
        target = args["target"]
        try:
            artifact = self.service.promote_evidence(
                evidence_id,
                target,
                job_id=args.get("job_id"),
                statement=args.get("statement"),
                name=args.get("name"),
                importance=args.get("importance"),
                satisfaction=args.get("satisfaction"),
            )
        except EvidenceNotFoundError:
            return _evidence_id_error(evidence_id)
        except JobNotFoundError:
            return _job_id_error(args.get("job_id", ""))
        except StepNotFoundError:
            return _step_id_error(args.get("step_id", ""))
        except OutcomeNotFoundError:
            return _outcome_id_error(args.get("outcome_id", ""))
        except ValueOutOfRangeError:
            return _VALUE_RANGE_ERROR
        except ValueError as exc:
            return f"Error: {exc}"
        label = "Job" if target == "job" else "Outcome"
        return f"{label} created successfully: {artifact.model_dump_json()}"

    def _get_odi_schema(self, args: dict) -> str:
        return json.dumps(odi_schema())

    def _compute_opportunity(self, args: dict) -> str:
        importance = args["importance"]
        satisfaction = args["satisfaction"]
        if not (1.0 <= importance <= 10.0) or not (1.0 <= satisfaction <= 10.0):
            return _VALUE_RANGE_ERROR
        score = self.service.compute_opportunity(importance, satisfaction)
        return f"Opportunity score: {score:.2f}"


class MCPBackend(Backend):
    def __init__(self, mcp_url: str) -> None:
        self.mcp_url = mcp_url

    def call(self, tool_name: str, args: dict) -> str:
        return _call_mcp(tool_name, args, self.mcp_url)


@dataclass
class BackendConfig:
    backend: str | None = None
    db_path: str | None = None
    mcp_url: str | None = None


def get_backend(
    backend: str | None = None, db_path: str | None = None, mcp_url: str | None = None
) -> Backend:
    if backend is None:
        backend = os.environ.get("AGENTIC_ODI_BACKEND", "local")
    if backend == "local":
        return LocalBackend(db_path=db_path)
    if backend == "mcp":
        return MCPBackend(
            mcp_url or os.environ.get("AGENTIC_ODI_MCP_URL", "http://localhost:8000/mcp")
        )
    raise ValueError(f"Unknown backend: {backend}")


def resolve_backend(config: BackendConfig) -> Backend:
    if config.backend == "mcp" and config.db_path:
        typer.echo("Warning: db_path is ignored when backend is 'mcp'", err=True)
    return get_backend(backend=config.backend, db_path=config.db_path, mcp_url=config.mcp_url)


def require_backend(ctx: typer.Context) -> Backend:
    """Resolve the backend stored on the Typer context."""
    backend = ctx.obj
    if isinstance(backend, Backend):
        return backend
    if isinstance(backend, BackendConfig):
        resolved = resolve_backend(backend)
        ctx.obj = resolved
        return resolved
    typer.echo("Error: no backend configured", err=True)
    raise typer.Exit(code=1)
